1	package shadow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"math/big"
7		"reflect"
8		"sort"
9		"strings"
10		"time"
11	)
12	
13	// DiffEntry 描述期望配置与上报配置之间的一处差异。
14	type DiffEntry struct {
15		// Path 是差异位置的 JSON Pointer（RFC 6901），如 "/wifi/ssid"。
16		Path string
17		// DesiredExists 表示期望配置在该路径是否存在值。
18		DesiredExists bool
19		// ReportedExists 表示上报配置在该路径是否存在值。
20		ReportedExists bool
21		// Desired 是期望配置在该路径的原始 JSON，不存在时为 nil。
22		Desired json.RawMessage
23		// Reported 是上报配置在该路径的原始 JSON，不存在时为 nil。
24		Reported json.RawMessage
25		// Since 是该路径的差异首次出现的时间。
26		Since time.Time
27	}
28	
29	// computeDiff 计算两份 JSON 对象配置之间的差异，按路径字典序返回。
30	// desired 与 reported 必须都是 JSON 对象（调用方保证）。
31	func computeDiff(desired, reported json.RawMessage) []DiffEntry {
32		dObj, _ := decodeObject(desired)
33		rObj, _ := decodeObject(reported)
34		var out []DiffEntry
35		walkObject("", dObj, rObj, &out)
36		sort.Slice(out, func(i, j int) bool { return out[i].Path < out[j].Path })
37		return out
38	}
39	
40	// walkObject 递归比较两个对象。prefix 是当前路径前缀。
41	func walkObject(prefix string, d, r map[string]json.RawMessage, out *[]DiffEntry) {
42		keys := make([]string, 0, len(d)+len(r))
43		seen := make(map[string]bool, len(d)+len(r))
44		for k := range d {
45			seen[k] = true
46			keys = append(keys, k)
47		}
48		for k := range r {
49			if !seen[k] {
50				keys = append(keys, k)
51			}
52		}
53		for _, k := range keys {
54			path := prefix + "/" + escapePointer(k)
55			dv, dok := d[k]
56			rv, rok := r[k]
57			switch {
58			case dok && !rok:
59				// 一侧整个字段不存在：只在该字段处列一条差异，不再下钻。
60				*out = append(*out, DiffEntry{Path: path, DesiredExists: true, Desired: cloneRaw(dv)})
61			case !dok && rok:
62				*out = append(*out, DiffEntry{Path: path, ReportedExists: true, Reported: cloneRaw(rv)})
63			default:
64				dSub, dIsObj := asObject(dv)
65				rSub, rIsObj := asObject(rv)
66				if dIsObj && rIsObj {
67					// 双方均为对象：逐层比较。
68					walkObject(path, dSub, rSub, out)
69				} else if !rawEqual(dv, rv) {
70					// 其他值（含数组、null）按整体比较，数组不拆分。
71					*out = append(*out, DiffEntry{
72						Path:           path,
73						DesiredExists:  true,
74						ReportedExists: true,
75						Desired:        cloneRaw(dv),
76						Reported:       cloneRaw(rv),
77					})
78				}
79			}
80		}
81	}
82	
83	// escapePointer 按 RFC 6901 转义路径段。
84	func escapePointer(s string) string {
85		s = strings.ReplaceAll(s, "~", "~0")
86		s = strings.ReplaceAll(s, "/", "~1")
87		return s
88	}
89	
90	// decodeObject 把 raw 解析为 JSON 对象；raw 非对象时返回 false。
91	func decodeObject(raw json.RawMessage) (map[string]json.RawMessage, bool) {
92		trimmed := bytes.TrimSpace(raw)
93		if len(trimmed) == 0 || trimmed[0] != '{' {
94			return nil, false
95		}
96		var obj map[string]json.RawMessage
97		dec := json.NewDecoder(bytes.NewReader(trimmed))
98		if err := dec.Decode(&obj); err != nil {
99			return nil, false
100		}
101		if obj == nil { // "null" 已通过首字符排除，这里防御性处理
102			obj = map[string]json.RawMessage{}
103		}
104		return obj, true
105	}
106	
107	func asObject(raw json.RawMessage) (map[string]json.RawMessage, bool) {
108		return decodeObject(raw)
109	}
110	
111	// validateConfig 校验配置必须是合法的 JSON 对象，并返回独立副本。
112	func validateConfig(raw json.RawMessage) (json.RawMessage, error) {
113		if _, ok := decodeObject(raw); !ok {
114			return nil, ErrInvalidConfig
115		}
116		return cloneRaw(raw), nil
117	}
118	
119	// rawEqual 比较两份 JSON 值是否语义相等：忽略对象字段顺序，
120	// 数字按数值比较（1 与 1.0 相等），其余按类型与值比较。
121	func rawEqual(a, b json.RawMessage) bool {
122		av, err := decodeValue(a)
123		if err != nil {
124			return false
125		}
126		bv, err := decodeValue(b)
127		if err != nil {
128			return false
129		}
130		return jsonDeepEqual(av, bv)
131	}
132	
133	func decodeValue(raw json.RawMessage) (any, error) {
134		dec := json.NewDecoder(bytes.NewReader(raw))
135		dec.UseNumber()
136		var v any
137		if err := dec.Decode(&v); err != nil {
138			return nil, err
139		}
140		return v, nil
141	}
142	
143	func jsonDeepEqual(a, b any) bool {
144		switch av := a.(type) {
145		case map[string]any:
146			bv, ok := b.(map[string]any)
147			if !ok || len(av) != len(bv) {
148				return false
149			}
150			for k, va := range av {
151				vb, ok := bv[k]
152				if !ok || !jsonDeepEqual(va, vb) {
153					return false
154				}
155			}
156			return true
157		case []any:
158			bv, ok := b.([]any)
159			if !ok || len(av) != len(bv) {
160				return false
161			}
162			for i := range av {
163				if !jsonDeepEqual(av[i], bv[i]) {
164					return false
165				}
166			}
167			return true
168		case json.Number:
169			bv, ok := b.(json.Number)
170			if !ok {
171				return false
172			}
173			return numberEqual(av, bv)
174		default:
175			return reflect.DeepEqual(a, b)
176		}
177	}
178	
179	func numberEqual(a, b json.Number) bool {
180		if a.String() == b.String() {
181			return true
182		}
183		ra, okA := new(big.Rat).SetString(a.String())
184		rb, okB := new(big.Rat).SetString(b.String())
185		if okA && okB {
186			return ra.Cmp(rb) == 0
187		}
188		return false
189	}
190	
191	func cloneRaw(raw json.RawMessage) json.RawMessage {
192		if raw == nil {
193			return nil
194		}
195		out := make(json.RawMessage, len(raw))
196		copy(out, raw)
197		return out
198	}
