1	package shadow
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"time"
7	)
8	
9	// diskVersion 是升级版本登记的磁盘格式。
10	type diskVersion struct {
11		Target      string   `json:"target"`
12		AllowedFrom []string `json:"allowedFrom"`
13	}
14	
15	// diskCampaign 是活动的磁盘格式，设备按提交次序保存。
16	type diskCampaign struct {
17		ID                string       `json:"id"`
18		Operator          string       `json:"operator"`
19		Target            string       `json:"target"`
20		CreatedAt         time.Time    `json:"createdAt"`
21		BatchSize         int          `json:"batchSize"`
22		WindowStart       time.Time    `json:"windowStart"`
23		WindowEnd         time.Time    `json:"windowEnd"`
24		Deadline          time.Time    `json:"deadline"`
25		RollbackOnFailure bool         `json:"rollbackOnFailure,omitempty"`
26		LastTime          time.Time    `json:"lastTime"`
27		Status            string       `json:"status"`
28		Ended             bool         `json:"ended"`
29		EndedAt           time.Time    `json:"endedAt,omitempty"`
30		Devices           []diskDev    `json:"devices"`
31		Results           []diskResult `json:"results,omitempty"`
32	}
33	
34	type diskOp struct {
35		ID            string          `json:"id"`
36		Claimed       bool            `json:"claimed"`
37		ClaimedAt     time.Time       `json:"claimedAt,omitempty"`
38		HasResult     bool            `json:"hasResult"`
39		Success       bool            `json:"success"`
40		Reason        string          `json:"reason,omitempty"`
41		At            time.Time       `json:"at,omitempty"`
42		ResultSeq     uint64          `json:"resultSeq,omitempty"`
43		ResultVersion string          `json:"resultVersion,omitempty"`
44		ResultConfig  json.RawMessage `json:"resultConfig,omitempty"`
45	}
46	
47	type diskDev struct {
48		DeviceID       string    `json:"deviceId"`
49		Batch          int       `json:"batch"`
50		Status         string    `json:"status"`
51		Phase          string    `json:"phase"`
52		Reason         string    `json:"reason,omitempty"`
53		At             time.Time `json:"at,omitempty"`
54		Download       diskOp    `json:"download"`
55		Install        diskOp    `json:"install"`
56		Rollback       diskOp    `json:"rollback,omitempty"`
57		RollbackTarget string    `json:"rollbackTarget,omitempty"`
58	}
59	
60	type diskResult struct {
61		DeviceID    string    `json:"deviceId"`
62		OperationID string    `json:"operationId"`
63		Stage       string    `json:"stage"`
64		Success     bool      `json:"success"`
65		Reason      string    `json:"reason,omitempty"`
66		Version     string    `json:"version,omitempty"`
67		At          time.Time `json:"at"`
68	}
69	
70	func (s *Store) marshalVersions() map[string]diskVersion {
71		out := make(map[string]diskVersion, len(s.versions))
72		for k, v := range s.versions {
73			out[k] = diskVersion{Target: v.Target, AllowedFrom: append([]string(nil), v.AllowedFrom...)}
74		}
75		return out
76	}
77	
78	func (s *Store) marshalCampaigns() (map[string]diskCampaign, error) {
79		out := make(map[string]diskCampaign, len(s.campaigns))
80		for id, c := range s.campaigns {
81			dc := diskCampaign{
82				ID:                c.ID,
83				Operator:          c.Operator,
84				Target:            c.Target,
85				CreatedAt:         c.CreatedAt,
86				BatchSize:         c.BatchSize,
87				WindowStart:       c.WindowStart,
88				WindowEnd:         c.WindowEnd,
89				Deadline:          c.Deadline,
90				RollbackOnFailure: c.RollbackOnFailure,
91				LastTime:          c.LastTime,
92				Status:            c.Status,
93				Ended:             c.Ended,
94				EndedAt:           c.EndedAt,
95				Results:           make([]diskResult, 0, len(c.Results)),
96			}
97			for _, cd := range c.Devices {
98				dc.Devices = append(dc.Devices, diskDev{
99					DeviceID:       cd.DeviceID,
100					Batch:          cd.Batch,
101					Status:         cd.Status,
102					Phase:          cd.Phase,
103					Reason:         cd.Reason,
104					At:             cd.At,
105					Download:       encodeOp(cd.Download),
106					Install:        encodeOp(cd.Install),
107					Rollback:       encodeOp(cd.Rollback),
108					RollbackTarget: cd.RollbackTarget,
109				})
110			}
111			for _, r := range c.Results {
112				dc.Results = append(dc.Results, diskResult{
113					DeviceID:    r.DeviceID,
114					OperationID: r.OperationID,
115					Stage:       r.Stage,
116					Success:     r.Success,
117					Reason:      r.Reason,
118					Version:     r.Version,
119					At:          r.At,
120				})
121			}
122			out[id] = dc
123		}
124		return out, nil
125	}
126	
127	func encodeOp(o opState) diskOp {
128		return diskOp{
129			ID:            o.ID,
130			Claimed:       o.Claimed,
131			ClaimedAt:     o.ClaimedAt,
132			HasResult:     o.HasResult,
133			Success:       o.Success,
134			Reason:        o.Reason,
135			At:            o.At,
136			ResultSeq:     o.ResultSeq,
137			ResultVersion: o.ResultVersion,
138			ResultConfig:  cloneRaw(o.ResultConfig),
139		}
140	}
141	
142	func decodeOp(d diskOp) opState {
143		return opState{
144			ID:            d.ID,
145			Claimed:       d.Claimed,
146			ClaimedAt:     d.ClaimedAt,
147			HasResult:     d.HasResult,
148			Success:       d.Success,
149			Reason:        d.Reason,
150			At:            d.At,
151			ResultSeq:     d.ResultSeq,
152			ResultVersion: d.ResultVersion,
153			ResultConfig:  cloneRaw(d.ResultConfig),
154		}
155	}
156	
157	// restoreVersions 恢复并校验版本登记。
158	func (s *Store) restoreVersions(disk map[string]diskVersion) error {
159		out := make(map[string]*versionState, len(disk))
160		for k, dv := range disk {
161			if k == "" || dv.Target == "" || k != dv.Target {
162				return fmt.Errorf("%w: invalid upgrade version entry", ErrCorruptStorage)
163			}
164			if err := validateAllowedFrom(dv.Target, dv.AllowedFrom); err != nil {
165				return fmt.Errorf("%w: version %s: %v", ErrCorruptStorage, dv.Target, err)
166			}
167			out[k] = &versionState{Target: dv.Target, AllowedFrom: append([]string(nil), dv.AllowedFrom...)}
168		}
169		s.versions = out
170		return nil
171	}
172	
173	// restoreCampaigns 恢复活动并做一致性校验。版本、设备引用、操作标识、
174	// 结果历史都必须自洽，否则整个存储拒绝打开。
175	func (s *Store) restoreCampaigns(disk map[string]diskCampaign) error {
176		out := make(map[string]*campaignState, len(disk))
177		for id, dc := range disk {
178			if id == "" || dc.ID != id {
179				return fmt.Errorf("%w: campaign id mismatch", ErrCorruptStorage)
180			}
181			if dc.Operator == "" || dc.Target == "" || dc.BatchSize <= 0 {
182				return fmt.Errorf("%w: campaign %s invalid", ErrCorruptStorage, id)
183			}
184			if dc.CreatedAt.IsZero() || dc.WindowStart.IsZero() || dc.WindowEnd.IsZero() || dc.Deadline.IsZero() {
185				return fmt.Errorf("%w: campaign %s missing time", ErrCorruptStorage, id)
186			}
187			if !dc.WindowStart.Before(dc.WindowEnd) || !dc.Deadline.After(dc.CreatedAt) {
188				return fmt.Errorf("%w: campaign %s invalid time range", ErrCorruptStorage, id)
189			}
190			if _, ok := s.versions[dc.Target]; !ok {
191				return fmt.Errorf("%w: campaign %s target %s missing", ErrCorruptStorage, id, dc.Target)
192			}
193			if dc.Status != CampaignRunning && dc.Status != CampaignSucceeded && dc.Status != CampaignFailed {
194				return fmt.Errorf("%w: campaign %s bad status", ErrCorruptStorage, id)
195			}
196			if dc.Ended == (dc.Status == CampaignRunning) {
197				return fmt.Errorf("%w: campaign %s ended/status mismatch", ErrCorruptStorage, id)
198			}
199			if len(dc.Devices) == 0 {
200				return fmt.Errorf("%w: campaign %s has no devices", ErrCorruptStorage, id)
201			}
202			c := &campaignState{
203				ID:                dc.ID,
204				Operator:          dc.Operator,
205				Target:            dc.Target,
206				CreatedAt:         dc.CreatedAt,
207				BatchSize:         dc.BatchSize,
208				WindowStart:       dc.WindowStart,
209				WindowEnd:         dc.WindowEnd,
210				Deadline:          dc.Deadline,
211				RollbackOnFailure: dc.RollbackOnFailure,
212				LastTime:          dc.LastTime,
213				Status:            dc.Status,
214				Ended:             dc.Ended,
215				EndedAt:           dc.EndedAt,
216				index:             map[string]int{},
217			}
218			if c.LastTime.IsZero() {
219				c.LastTime = c.CreatedAt
220			}
221			if c.LastTime.Before(c.CreatedAt) {
222				return fmt.Errorf("%w: campaign %s last time before creation", ErrCorruptStorage, id)
223			}
224			seen := map[string]bool{}
225			for i, dd := range dc.Devices {
226				if dd.DeviceID == "" || seen[dd.DeviceID] {
227					return fmt.Errorf("%w: campaign %s device list invalid", ErrCorruptStorage, id)
228				}
229				seen[dd.DeviceID] = true
230				if _, ok := s.devices[dd.DeviceID]; !ok {
231					return fmt.Errorf("%w: campaign %s device %s missing", ErrCorruptStorage, id, dd.DeviceID)
232				}
233				if dd.Batch != i/dc.BatchSize {
234					return fmt.Errorf("%w: campaign %s batch mismatch", ErrCorruptStorage, id)
235				}
236				if !validDeviceStatus(dd.Status) {
237					return fmt.Errorf("%w: campaign %s bad device status", ErrCorruptStorage, id)
238				}
239				if dd.Phase != StageDownload && dd.Phase != StageInstall && dd.Phase != StageRollback {
240					return fmt.Errorf("%w: campaign %s bad phase", ErrCorruptStorage, id)
241				}
242				wantDL := operationID(id, dd.DeviceID, StageDownload)
243				wantIN := operationID(id, dd.DeviceID, StageInstall)
244				wantRB := operationID(id, dd.DeviceID, StageRollback)
245				if dd.Download.ID != wantDL || dd.Install.ID != wantIN {
246					return fmt.Errorf("%w: campaign %s operation id mismatch", ErrCorruptStorage, id)
247				}
248				if dc.RollbackOnFailure {
249					if dd.Rollback.ID != wantRB {
250						return fmt.Errorf("%w: campaign %s rollback op id mismatch", ErrCorruptStorage, id)
251					}
252				} else {
253					// 未开启回滚的活动（含旧存储）不得残留任何回滚进展；
254					// 回滚标识允许缺省（旧存储）或等于稳定标识（新存储）。
255					if dd.Rollback.ID != "" && dd.Rollback.ID != wantRB {
256						return fmt.Errorf("%w: campaign %s rollback op id mismatch", ErrCorruptStorage, id)
257					}
258					if dd.RollbackTarget != "" ||
259						dd.Rollback.Claimed || dd.Rollback.HasResult ||
260						dd.Status == DeviceAwaitingRollback || dd.Status == DeviceRollingBack ||
261						dd.Phase == StageRollback || isRollbackTerminal(dd.Status) {
262						return fmt.Errorf("%w: campaign %s rollback state in non-rollback campaign", ErrCorruptStorage, id)
263					}
264				}
265				// 终态设备必须带时间；失败还须带阶段与原因。
266				if isTerminal(dd.Status) && dd.At.IsZero() {
267					return fmt.Errorf("%w: campaign %s terminal without time", ErrCorruptStorage, id)
268				}
269				if dd.Status == DeviceFailed && dd.Reason == "" {
270					return fmt.Errorf("%w: campaign %s failure without reason", ErrCorruptStorage, id)
271				}
272				if (dd.Status == DeviceRollbackFailed || dd.Status == DeviceRollbackTimeout ||
273					dd.Status == DeviceAwaitingRollback) && dd.Reason == "" {
274					return fmt.Errorf("%w: campaign %s rollback without reason", ErrCorruptStorage, id)
275				}
276				if dd.Status == DeviceSucceeded &&
277					!(dd.Download.HasResult && dd.Download.Success && dd.Install.HasResult && dd.Install.Success) {
278					return fmt.Errorf("%w: campaign %s succeeded device without results", ErrCorruptStorage, id)
279				}
280				if dd.Status == DeviceFailed {
281					failedOp := dd.Download
282					if dd.Phase == StageInstall {
283						failedOp = dd.Install
284					}
285					if !failedOp.HasResult || failedOp.Success {
286						return fmt.Errorf("%w: campaign %s failed device without failed result", ErrCorruptStorage, id)
287					}
288				}
289				if dd.Status == DeviceReady && !(dd.Download.HasResult && dd.Download.Success) {
290					return fmt.Errorf("%w: campaign %s ready device without download", ErrCorruptStorage, id)
291				}
292				ops := []diskOp{dd.Download, dd.Install}
293				if dc.RollbackOnFailure {
294					ops = append(ops, dd.Rollback)
295				}
296				for _, o := range ops {
297					if o.HasResult {
298						if !o.Claimed {
299							return fmt.Errorf("%w: campaign %s unclaimed result", ErrCorruptStorage, id)
300						}
301						if o.At.IsZero() {
302							return fmt.Errorf("%w: campaign %s result without time", ErrCorruptStorage, id)
303						}
304						if !o.Success && o.Reason == "" {
305							return fmt.Errorf("%w: campaign %s failed result without reason", ErrCorruptStorage, id)
306						}
307					}
308					if o.Claimed && o.ClaimedAt.IsZero() {
309						return fmt.Errorf("%w: campaign %s claim without time", ErrCorruptStorage, id)
310					}
311				}
312				if dd.Install.HasResult && !(dd.Download.HasResult && dd.Download.Success) {
313					return fmt.Errorf("%w: campaign %s install before download", ErrCorruptStorage, id)
314				}
315				if dd.Install.Claimed && !(dd.Download.HasResult && dd.Download.Success) {
316					return fmt.Errorf("%w: campaign %s install claimed before download", ErrCorruptStorage, id)
317				}
318				if dd.Install.HasResult && dd.Install.Success {
319					if dd.Install.ResultVersion != dc.Target {
320						return fmt.Errorf("%w: campaign %s install version mismatch", ErrCorruptStorage, id)
321					}
322					if _, ok := decodeObject(dd.Install.ResultConfig); !ok {
323						return fmt.Errorf("%w: campaign %s install config invalid", ErrCorruptStorage, id)
324					}
325				}
326				if dc.RollbackOnFailure {
327					if err := validateRollbackDisk(id, dd); err != nil {
328						return err
329					}
330				}
331				rbOp := decodeOp(dd.Rollback)
332				if !dc.RollbackOnFailure {
333					// 与创建路径一致：内存中始终持有稳定的回滚操作标识。
334					rbOp = opState{ID: wantRB}
335				}
336				cd := &campaignDevice{
337					DeviceID:       dd.DeviceID,
338					Batch:          dd.Batch,
339					Status:         dd.Status,
340					Phase:          dd.Phase,
341					Reason:         dd.Reason,
342					At:             dd.At,
343					Download:       decodeOp(dd.Download),
344					Install:        decodeOp(dd.Install),
345					Rollback:       rbOp,
346					RollbackTarget: dd.RollbackTarget,
347				}
348				c.index[cd.DeviceID] = len(c.Devices)
349				c.Devices = append(c.Devices, cd)
350			}
351			seenResult := map[string]bool{}
352			for _, dr := range dc.Results {
353				if dr.At.IsZero() {
354					return fmt.Errorf("%w: campaign %s result without time", ErrCorruptStorage, id)
355				}
356				if _, ok := c.index[dr.DeviceID]; !ok {
357					return fmt.Errorf("%w: campaign %s result device mismatch", ErrCorruptStorage, id)
358				}
359				if dr.Stage != StageDownload && dr.Stage != StageInstall && dr.Stage != StageRollback {
360					return fmt.Errorf("%w: campaign %s result stage invalid", ErrCorruptStorage, id)
361				}
362				if dr.Stage == StageRollback && !dc.RollbackOnFailure {
363					return fmt.Errorf("%w: campaign %s rollback result in non-rollback campaign", ErrCorruptStorage, id)
364				}
365				wantOp := operationID(id, dr.DeviceID, dr.Stage)
366				if dr.OperationID != wantOp {
367					return fmt.Errorf("%w: campaign %s result op id mismatch", ErrCorruptStorage, id)
368				}
369				key := dr.OperationID
370				if seenResult[key] {
371					return fmt.Errorf("%w: campaign %s duplicated result history", ErrCorruptStorage, id)
372				}
373				seenResult[key] = true
374				if !dr.Success && dr.Reason == "" {
375					return fmt.Errorf("%w: campaign %s failed result without reason", ErrCorruptStorage, id)
376				}
377				c.Results = append(c.Results, ResultRecord{
378					DeviceID:    dr.DeviceID,
379					OperationID: dr.OperationID,
380					Stage:       dr.Stage,
381					Success:     dr.Success,
382					Reason:      dr.Reason,
383					Version:     dr.Version,
384					At:          dr.At,
385				})
386			}
387			out[id] = c
388		}
389		// 设备不能同时参加多个未结束活动。
390		busy := map[string]string{}
391		for id, c := range out {
392			if c.Ended {
393				continue
394			}
395			for _, cd := range c.Devices {
396				if other, ok := busy[cd.DeviceID]; ok {
397					return fmt.Errorf("%w: device %s in active campaigns %s and %s",
398						ErrCorruptStorage, cd.DeviceID, other, id)
399				}
400				busy[cd.DeviceID] = id
401			}
402		}
403		s.campaigns = out
404		return nil
405	}
406	
407	func validDeviceStatus(status string) bool {
408		switch status {
409		case DevicePending, DeviceDownloading, DeviceReady, DeviceInstalling,
410			DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
411			DeviceAwaitingRollback, DeviceRollingBack,
412			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
413			return true
414		default:
415			return false
416		}
417	}
418	
419	// isRollbackTerminal 判断状态是否属于回滚相关终态。
420	func isRollbackTerminal(status string) bool {
421		switch status {
422		case DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
423			return true
424		default:
425			return false
426		}
427	}
428	
429	// isRollbackFlowStatus 判断状态是否处于回滚流程（等待/进行中/任一回滚终态）。
430	func isRollbackFlowStatus(status string) bool {
431		switch status {
432		case DeviceAwaitingRollback, DeviceRollingBack,
433			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
434			return true
435		default:
436			return false
437		}
438	}
439	
440	// validateRollbackDisk 校验开启回滚的活动中单台设备的回滚状态自洽。
441	func validateRollbackDisk(campaignID string, dd diskDev) error {
442		bad := func(msg string) error {
443			return fmt.Errorf("%w: campaign %s device %s %s", ErrCorruptStorage, campaignID, dd.DeviceID, msg)
444		}
445		rb := dd.Rollback
446		// 回滚目标只能在首次领取下载时或之后锁定：有目标就必已领取下载。
447		// 反向不成立——领取下载时复查版本不兼容会直接失败，不锁定目标、也不回滚。
448		if dd.RollbackTarget != "" && !dd.Download.Claimed {
449			return bad("rollback target locked before download claim")
450		}
451		// 进入回滚流程的设备必然经过成功下载，目标一定已锁定。
452		if isRollbackFlowStatus(dd.Status) && dd.RollbackTarget == "" {
453			return bad("rollback status without locked target")
454		}
455		switch dd.Status {
456		case DeviceAwaitingRollback:
457			// 已接受安装失败、回滚尚未领取：回滚无结果。
458			if dd.Phase != StageRollback || rb.Claimed || rb.HasResult {
459				return bad("awaiting rollback state mismatch")
460			}
461			if !(dd.Install.HasResult && !dd.Install.Success) {
462				return bad("awaiting rollback without install failure")
463			}
464		case DeviceRollingBack:
465			if dd.Phase != StageRollback || !rb.Claimed || rb.HasResult {
466				return bad("rolling back state mismatch")
467			}
468		case DeviceRollbackSucceeded:
469			if dd.Phase != StageRollback || !rb.HasResult || !rb.Success {
470				return bad("rollback succeeded without success result")
471			}
472			if rb.ResultVersion != dd.RollbackTarget {
473				return bad("rollback version mismatch")
474			}
475			if _, ok := decodeObject(rb.ResultConfig); !ok {
476				return bad("rollback config invalid")
477			}
478		case DeviceRollbackFailed:
479			if dd.Phase != StageRollback || !rb.HasResult || rb.Success || rb.Reason == "" {
480				return bad("rollback failed without failure result")
481			}
482		case DeviceRollbackTimeout:
483			if dd.Phase != StageRollback {
484				return bad("rollback timeout phase mismatch")
485			}
486			// 等待回滚超时（未领取）或正在回滚超时（已领取未完成）都可能。
487			if rb.HasResult {
488				return bad("rollback timeout with result")
489			}
490		default:
491			// 其余状态：开启回滚后安装一旦失败必然进入回滚流程，
492			// 因此这里不能有安装失败，回滚操作也必须从未被领取或提交；
493			// 但回滚目标可能因已领取下载而存在（下载失败/超时/成功等）。
494			if dd.Install.HasResult && !dd.Install.Success {
495				return bad("install failure without rollback state")
496			}
497			if rb.Claimed || rb.HasResult {
498				return bad("rollback progressed without install failure")
499			}
500		}
501		return nil
502	}
503

