350	// Claim 由调用方传入当前时间，为活动中的设备领取当前可执行的操作。
351	//
352	// 派发新的下载或安装操作要求设备在线、当前时间位于维护窗口 [start, end) 内、
353	// 所在批次已被前一批全部成功放行。首次领取下载前会再次核对设备当前版本，
354	// 不兼容则将该设备（带阶段、原因和时间）记为失败，返回 ErrIncompatibleVersion；
355	// 开启回滚的活动还会在首次领取下载时把设备当时的当前版本锁定为回滚目标，
356	// 后续普通上报不改变它。
357	// 开启回滚且安装失败已被接受后，设备领取回滚操作：首次领取同样要求设备在线
358	// 且时间位于原维护窗口 [start, end) 内（不受批次放行影响），返回的操作带锁定
359	// 目标版本；离线或窗口外保留待办。回滚已领取但未完成时再次查询返回同一标识，
360	// 且可在窗口外、截止前提交结果。
361	// 已领取但未完成的操作（下载/安装/回滚）再次查询时返回同一标识，不要求在线或位于窗口内。
362	// 离线设备保留待办；离线或窗口外暂无可领取的新操作时返回 (nil, nil)。
363	// 时间缺失或相对本活动已接受的时间倒退时拒绝，且不改变状态。
364	func (s *Store) Claim(campaignID, deviceID string, at time.Time) (*Operation, error) {
365		s.mu.Lock()
366		defer s.mu.Unlock()
367		if err := s.checkOpen(); err != nil {
368			return nil, err
369		}
370		c, cd, err := s.lookupCampaignDevice(campaignID, deviceID)
371		if err != nil {
372			return nil, err
373		}
374		if at.IsZero() {
375			return nil, ErrInvalidTime
376		}
377		if at.Before(c.LastTime) {
378			return nil, fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
379		}
380		var op *Operation
381		var reject error
382		err = s.commit(func() error {
383			// 到达截止时间：未结束设备全部超时并落盘，本次领取拒绝。
384			// 即使查询的设备已有终态，其他未结束设备仍要级联超时。
385			if !at.Before(c.Deadline) {
386				c.LastTime = at
387				s.applyTimeout(c, at)
388				reject = ErrCampaignEnded
389				return nil
390			}
391			if c.Ended {
392				// 纯拒绝路径：不推进时间基线，不改状态。
393				reject = ErrCampaignEnded
394				return nil
395			}
396			if isTerminal(cd.Status) {
397				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, deviceID)
398				return nil
399			}
400			c.LastTime = at
401			// 已领取但未完成的操作：查询仍返回原标识，不要求在线或位于窗口内。
402			if out := outstandingOp(c, cd); out != nil {
403				op = out
404				return nil
405			}
406			// 安装失败已接受、等待回滚：回滚是该设备的善后操作，不受批次放行影响。
407			// 首次领取要求在线且位于原维护窗口 [start,end) 内；离线或窗口外保留待办。
408			if cd.Status == DeviceAwaitingRollback {
409				if !s.devices[deviceID].Online {
410					return nil
411				}
412				if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
413					return nil
414				}
415				cd.Rollback.Claimed = true
416				cd.Rollback.ClaimedAt = at
417				cd.Status = DeviceRollingBack
418				cd.Phase = StageRollback
419				cd.At = at
420				op = &Operation{
421					ID:            cd.Rollback.ID,
422					CampaignID:    c.ID,
423					DeviceID:      deviceID,
424					Kind:          StageRollback,
425					TargetVersion: cd.RollbackTarget,
426				}
427				return nil
428			}
429			// 尚未领取的新阶段：先看批次是否放行（不放行时无操作可领）。
430			if !s.batchOpen(c, cd) {
431				return nil
432			}
433			if !s.devices[deviceID].Online {
434				return nil // 离线保留待办，上线后继续
435			}
436			if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
437				return nil // 窗口外不派发新操作；窗口为 [start, end)
438			}
439			if !cd.Download.Claimed {
440				// 首次领取下载前再次检查当前版本。
441				current := s.devices[deviceID].Version
442				if !containsString(s.versions[c.Target].AllowedFrom, current) {
443					reason := fmt.Sprintf("version %s is not compatible with target %s", current, c.Target)
444					// 该设备在下载阶段失败：领取即触发，记录阶段、原因和时间。
445					cd.Download.Claimed = true
446					cd.Download.ClaimedAt = at
447					cd.Download.HasResult = true
448					cd.Download.Success = false
449					cd.Download.Reason = reason
450					cd.Download.At = at
451					s.failDevice(c, cd, StageDownload, reason, at)
452					reject = fmt.Errorf("%w: device %s version %s", ErrIncompatibleVersion, deviceID, current)
453					return nil
454				}
455				// 开启回滚时，把首次领取下载时设备的当前版本锁定为回滚目标；
456				// 此后普通上报不改变它，也不要求该版本另行登记为升级目标。
457				if c.RollbackOnFailure && cd.RollbackTarget == "" {
458					cd.RollbackTarget = current
459				}
460				cd.Download.Claimed = true
461				cd.Download.ClaimedAt = at
462				cd.Status = DeviceDownloading
463				cd.At = at
464				op = &Operation{ID: cd.Download.ID, CampaignID: c.ID, DeviceID: deviceID, Kind: StageDownload}
465				return nil
466			}
467			// 下载已成功：领取安装（尚未领取的安装仍须在线且位于窗口内）。
468			cd.Install.Claimed = true
469			cd.Install.ClaimedAt = at
470			cd.Status = DeviceInstalling
471			cd.At = at
472			op = &Operation{ID: cd.Install.ID, CampaignID: c.ID, DeviceID: deviceID, Kind: StageInstall}
473			return nil
474		})
475		if err != nil {
476			return nil, err
477		}
478		if reject != nil {
479			return nil, reject
480		}
481		return op, nil
482	}
483	
484	// outstandingOp 返回设备已领取但尚无结果的操作；没有则返回 nil。
485	func outstandingOp(c *campaignState, cd *campaignDevice) *Operation {
486		switch {
487		case cd.Download.Claimed && !cd.Download.HasResult:
488			return &Operation{ID: cd.Download.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageDownload}
489		case cd.Install.Claimed && !cd.Install.HasResult:
490			return &Operation{ID: cd.Install.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageInstall}
491		case cd.Rollback.Claimed && !cd.Rollback.HasResult:
492			// 已领取但未完成的回滚再次领取仍返回同一标识，并继续告知恢复目标版本。
493			return &Operation{
494				ID:            cd.Rollback.ID,
495				CampaignID:    c.ID,
496				DeviceID:      cd.DeviceID,
497				Kind:          StageRollback,
498				TargetVersion: cd.RollbackTarget,
499			}
500		default:
501			return nil
502		}
503	}
504	
505	// batchOpen 判断设备所在批次是否已放行：前序所有设备必须全部成功。
506	func (s *Store) batchOpen(c *campaignState, cd *campaignDevice) bool {
507		for _, other := range c.Devices {
508			if other.Batch < cd.Batch && other.Status != DeviceSucceeded {
509				return false
510			}
511		}
512		return true
513	}
514	
515	// SubmitResult 接收设备提交的操作结果。
516	//
517	// 相同操作的相同结果重复提交返回成功，但不增加历史、不重复放行批次；
518	// 改用不同结果、跳过未领取阶段、提交未领取的回滚、提交其他设备的操作、
519	// 活动结束后的新结果均报错且不改变状态；已接受结果的重复提交在活动结束后仍有效。
520	// 下载完成后才能领取并安装；设备失败记录阶段、原因和时间，同批其他设备
521	// 继续完成，后续批次记为未执行。安装成功须附带版本等于目标版本的合规上报，
522	// 回滚成功须附带版本等于锁定回滚目标的合规上报，影子与活动在同一次持久化中更新。
523	// 开启回滚的活动中，安装失败不直接结束设备，而是保留原失败原因与时间、
524	// 令设备等待回滚；回滚失败必须给出原因，设备以回滚失败结束且影子不变。
525	// 普通设备上报不经过本方法，也不会推进活动。
526	func (s *Store) SubmitResult(res OperationResult) error {
527		s.mu.Lock()
528		defer s.mu.Unlock()
529		if err := s.checkOpen(); err != nil {
530			return err
531		}
532		c, cd, err := s.lookupCampaignDevice(res.CampaignID, res.DeviceID)
533		if err != nil {
534			return err
535		}
536		if res.At.IsZero() {
537			return ErrInvalidTime
538		}
539		// 定位操作标识所属阶段；不属于本设备的操作一律视为未知。
540		var stage string
541		var op *opState
542		switch res.OperationID {
543		case cd.Download.ID:
544			stage, op = StageDownload, &cd.Download
545		case cd.Install.ID:
546			stage, op = StageInstall, &cd.Install
547		case cd.Rollback.ID:
548			stage, op = StageRollback, &cd.Rollback
549		default:
550			return fmt.Errorf("%w: %s", ErrOperationNotFound, res.OperationID)
551		}
552		// 已接受结果：相同结果幂等（活动结束后仍有效，不增加历史、不重复放行），
553		// 不推进时间基线；不同结果冲突。均不改变状态。
554		if op.HasResult {
555			if resultMatches(op, res) {
556				return nil
557			}
558			return fmt.Errorf("%w: operation %s", ErrResultConflict, res.OperationID)
559		}
560		if res.At.Before(c.LastTime) {
561			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, res.At, c.LastTime)
562		}
563		if !op.Claimed {
564			// 标识是本设备未来阶段的操作但尚未领取：属于跳过阶段（含未领取的回滚）。
565			return fmt.Errorf("%w: %s", ErrOperationNotClaimed, res.OperationID)
566		}
567		if !res.Success && res.Reason == "" {
568			return ErrInvalidReason
569		}
570		if res.Success && (stage == StageInstall || stage == StageRollback) {
571			// 安装上报版本必须等于升级目标；回滚上报版本必须等于锁定的回滚目标。
572			wantVersion := c.Target
573			if stage == StageRollback {
574				wantVersion = cd.RollbackTarget
575			}
576			if err := s.validateSuccessReport(res, wantVersion); err != nil {
577				return err
578			}
579		}
580		var reject error
581		err = s.commit(func() error {
582			// 到达截止时间：未结束设备全部超时并落盘；新结果（非重复）不再接受。
583			// 未完成回滚的设备在这一时刻记为回滚阶段超时（见 applyTimeout）。
584			if !res.At.Before(c.Deadline) {
585				c.LastTime = res.At
586				s.applyTimeout(c, res.At)
587				reject = ErrCampaignEnded
588				return nil
589			}
590			if c.Ended {
591				// 活动结束后的新结果：拒绝且不改状态（重复结果已在提交前处理）。
592				reject = ErrCampaignEnded
593				return nil
594			}
595			if isTerminal(cd.Status) {
596				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, res.DeviceID)
597				return nil
598			}
599			c.LastTime = res.At
600			op.HasResult = true
601			op.Success = res.Success
602			op.Reason = res.Reason
603			op.At = res.At
604			if !res.Success {
605				switch {
606				case stage == StageInstall && c.RollbackOnFailure:
607					// 安装失败：保留原因和时间，设备转入等待回滚（非终态）；
608					// 同批其他设备继续，后续批次立即记为未执行，活动暂不结束。
609					s.enterRollback(c, cd, res.Reason, res.At)
610				case stage == StageRollback:
611					// 回滚失败必须给出原因：设备以回滚失败结束且影子不变。
612					s.finishRollbackFailure(c, cd, res.Reason, res.At)
613				default:
614					s.failDevice(c, cd, stage, res.Reason, res.At)
615				}
616				return nil
617			}
618			switch stage {
619			case StageDownload:
620				cd.Status = DeviceReady
621				cd.Phase = StageInstall
622				cd.Reason = ""
623				cd.At = res.At
624			case StageInstall:
625				// 安装成功：附带上报与活动同时更新、一起持久化。
626				s.applySuccessReport(cd.DeviceID, res, res.At)
627				op.ResultSeq = res.Seq
628				op.ResultVersion = res.Version
629				op.ResultConfig = cloneRaw(res.Config)
630				cd.Status = DeviceSucceeded
631				cd.Phase = StageInstall
632				cd.Reason = ""
633				cd.At = res.At
634			case StageRollback:
635				// 回滚成功：按上报规则更新影子（版本回到锁定目标），同时推进回滚状态。
636				// 期望配置、修订号与审计保持不变。
637				s.applySuccessReport(cd.DeviceID, res, res.At)
638				op.ResultSeq = res.Seq
639				op.ResultVersion = res.Version
640				op.ResultConfig = cloneRaw(res.Config)
641				cd.Status = DeviceRollbackSucceeded
642				cd.Phase = StageRollback
643				cd.Reason = ""
644				cd.At = res.At
645			}
646			c.Results = append(c.Results, ResultRecord{
647				DeviceID:    cd.DeviceID,
648				OperationID: op.ID,
649				Stage:       stage,
650				Success:     true,
651				Version:     op.ResultVersion,
652				At:          res.At,
653			})
654			s.settle(c, res.At)
655			return nil
656		})
657		if err != nil {
658			return err
659		}
660		return reject
661	}
662	
663	// resultMatches 判断提交是否为已接受结果的重复提交（同一操作、相同结果）。
664	// 安装成功结果还须附带相同的上报（序号、版本、配置）；发生时间不参与判定，
665	// 使活动结束后的重复提交仍然有效。
666	func resultMatches(op *opState, res OperationResult) bool {
667		if op.Success != res.Success || op.Reason != res.Reason {
668			return false
669		}
670		if op.Success && op.ResultSeq != 0 {
671			return op.ResultSeq == res.Seq &&
672				op.ResultVersion == res.Version &&
673				rawEqual(op.ResultConfig, res.Config)
674		}
675		return true
676	}
677	
678	// validateSuccessReport 按现有上报规则校验安装/回滚成功附带的设备上报，
679	// 且版本必须等于 wantVersion（安装为升级目标，回滚为锁定目标）。只校验，不改状态。
680	func (s *Store) validateSuccessReport(res OperationResult, wantVersion string) error {
681		d := s.devices[res.DeviceID]
682		if res.Seq == 0 {
683			return fmt.Errorf("%w: report sequence", ErrInvalidReport)
684		}
685		if res.Version == "" {
686			return fmt.Errorf("%w: report version", ErrInvalidReport)
687		}
688		if res.Version != wantVersion {
689			return fmt.Errorf("%w: version %s", ErrInvalidReport, res.Version)
690		}
691		if _, err := validateConfig(res.Config); err != nil {
692			return fmt.Errorf("%w: config", ErrInvalidReport)
693		}
694		switch {
695		case res.Seq < d.LastSeq:
696			return fmt.Errorf("%w: stale sequence", ErrInvalidReport)
697		case res.Seq == d.LastSeq:
698			if !(res.Version == d.Version && res.At.Equal(d.LastReportTime) && rawEqual(res.Config, d.Reported)) {
699				return fmt.Errorf("%w: sequence conflict", ErrInvalidReport)
700			}
701		}
702		return nil
703	}
704	
705	// applySuccessReport 按 Report 的既有规则写入影子（调用方已校验）。
706	// 只更新上报侧（版本、上报配置、序号、在线状态与配置差异），
707	// 不动期望配置、修订号与审计。
708	func (s *Store) applySuccessReport(deviceID string, res OperationResult, at time.Time) {
709		d := s.devices[deviceID]
710		if res.Seq == d.LastSeq {
711			// 相同序号的完全重复上报：影子不变，只随活动一起落盘。
712			return
713		}
714		d.Reported = cloneRaw(res.Config)
715		d.Version = res.Version
716		d.Online = true
717		d.LastSeq = res.Seq
718		d.LastReportTime = at
719		d.refreshDiff(at)
720	}
721	
722	// enterRollback 在开启回滚的活动中处理已接受的安装失败：
723	// 保留原安装失败的原因与时间，令设备等待回滚（非终态）；
724	// 同批其他设备可继续，后续批次立即记为未执行，但活动暂不结束。
725	func (s *Store) enterRollback(c *campaignState, cd *campaignDevice, reason string, at time.Time) {
726		cd.Status = DeviceAwaitingRollback
727		cd.Phase = StageRollback
728		cd.Reason = reason
729		cd.At = at
730		c.Results = append(c.Results, ResultRecord{
731			DeviceID:    cd.DeviceID,
732			OperationID: cd.Install.ID,
733			Stage:       StageInstall,
734			Success:     false,
735			Reason:      reason,
736			At:          at,
737		})
738		skipLaterBatches(c, cd, at)
739		// 不结束活动：设备进入非终态的等待回滚，活动要等其回滚结束。
740	}
741	
742	// finishRollbackFailure 处理已接受的回滚失败：必须给出原因，
743	// 设备以回滚失败结束，影子不变（失败结果不附带、不应用上报）。
744	func (s *Store) finishRollbackFailure(c *campaignState, cd *campaignDevice, reason string, at time.Time) {
745		cd.Status = DeviceRollbackFailed
746		cd.Phase = StageRollback
747		cd.Reason = reason
748		cd.At = at
749		c.Results = append(c.Results, ResultRecord{
750			DeviceID:    cd.DeviceID,
751			OperationID: cd.Rollback.ID,
752			Stage:       StageRollback,
753			Success:     false,
754			Reason:      reason,
755			At:          at,
756		})
757		s.settle(c, at)
758	}
759	
760	// skipLaterBatches 把后续批次中尚未结束的设备立即记为未执行。
761	func skipLaterBatches(c *campaignState, cd *campaignDevice, at time.Time) {
762		for _, other := range c.Devices {
763			if other.Batch > cd.Batch && !isTerminal(other.Status) {
764				other.Status = DeviceSkipped
765				other.Phase = pendingPhase(other)
766				other.Reason = "not executed: previous batch failed"
767				other.At = at
768			}
769		}
770	}
771	
772	// failDevice 将设备记为失败，记录阶段、原因和时间；后续批次全部记为未执行，
773	// 本批其他设备继续。若全部设备已到终态，则活动以失败结束。
774	func (s *Store) failDevice(c *campaignState, cd *campaignDevice, phase, reason string, at time.Time) {
775		cd.Status = DeviceFailed
776		cd.Phase = phase
777		cd.Reason = reason
778		cd.At = at
779		c.Results = append(c.Results, ResultRecord{
780			DeviceID:    cd.DeviceID,
781			OperationID: opIDFor(cd, phase),
782			Stage:       phase,
783			Success:     false,
784			Reason:      reason,
785			At:          at,
786		})
787		skipLaterBatches(c, cd, at)
788		s.settle(c, at)
789	}
790	
791	func opIDFor(cd *campaignDevice, phase string) string {
792		switch phase {
793		case StageInstall:
794			return cd.Install.ID
795		case StageRollback:
796			return cd.Rollback.ID
797		default:
798			return cd.Download.ID
799		}
800	}
801	
802	// pendingPhase 返回设备尚未完成的阶段：下载成功后停留在安装阶段。
803	func pendingPhase(cd *campaignDevice) string {
804		if cd.Download.HasResult && cd.Download.Success {
805			return StageInstall
806		}
807		return StageDownload
808	}
809	
810	// applyTimeout 在当前时间达到截止时间时，把所有未结束设备记为超时，
811	// 已有终态保持不变，活动记为失败并结束。等待回滚或正在回滚的设备
812	// 以回滚阶段超时结束；不改写或清空影子。
813	func (s *Store) applyTimeout(c *campaignState, at time.Time) {
814		if c.Ended {
815			return
816		}
817		for _, cd := range c.Devices {
818			if isTerminal(cd.Status) {
819				continue
820			}
821			switch cd.Status {
822			case DeviceAwaitingRollback, DeviceRollingBack:
823				cd.Status = DeviceRollbackTimeout
824				cd.Phase = StageRollback
825			default:
826				cd.Status = DeviceTimeout
827				cd.Phase = pendingPhase(cd)
828			}
829			cd.Reason = "deadline exceeded"
830			cd.At = at
831		}
832		c.Status = CampaignFailed
833		c.Ended = true
834		c.EndedAt = at
835	}
836	
837	// settle 在全部设备到达终态时结束活动：全部成功则成功，否则失败。
838	// 即使回滚成功，设备也不是 succeeded，活动仍为失败。
839	func (s *Store) settle(c *campaignState, at time.Time) {
840		allSucceeded := true
841		for _, cd := range c.Devices {
842			if !isTerminal(cd.Status) {
843				return
844			}
845			if cd.Status != DeviceSucceeded {
846				allSucceeded = false
847			}
848		}
849		c.Ended = true
850		c.EndedAt = at
851		if allSucceeded {
852			c.Status = CampaignSucceeded
853		} else {
854			c.Status = CampaignFailed
855		}
856	}
857	
858	func isTerminal(status string) bool {
859		switch status {
860		case DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
861			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
862			return true
863		default:
864			return false
865		}
866	}
867	
868	// AdvanceCampaign 用调用方给出的当前时间推进活动：到达截止时间时把未结束
869	// 设备全部记为超时并结束活动。时间缺失或相对已接受时间倒退时拒绝且不改状态。
870	// 未到截止时间或活动已结束时为空操作。
871	func (s *Store) AdvanceCampaign(campaignID string, at time.Time) error {
872		s.mu.Lock()
873		defer s.mu.Unlock()
874		if err := s.checkOpen(); err != nil {
875			return err
876		}
877		c, err := s.lookupCampaign(campaignID)
878		if err != nil {
879			return err
880		}
881		if at.IsZero() {
882			return ErrInvalidTime
883		}
884		if at.Before(c.LastTime) {
885			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
886		}
887		if c.Ended {
888			return nil
889		}
890		if at.Before(c.Deadline) {
891			// 仅推进时间基线也持久化，使重开后的倒退判断仍然有效。
892			return s.commit(func() error { c.LastTime = at; return nil })
893		}
894		return s.commit(func() error {
895			c.LastTime = at
896			s.applyTimeout(c, at)
897			return nil
898		})
899	}
900	
901	func (s *Store) lookupCampaign(campaignID string) (*campaignState, error) {
902		if campaignID == "" {
903			return nil, ErrInvalidCampaignID
904		}
905		c, ok := s.campaigns[campaignID]
906		if !ok {
907			return nil, fmt.Errorf("%w: %s", ErrCampaignNotFound, campaignID)
908		}
909		return c, nil
910	}
911	
912	func (s *Store) lookupCampaignDevice(campaignID, deviceID string) (*campaignState, *campaignDevice, error) {
913		c, err := s.lookupCampaign(campaignID)
914		if err != nil {
915			return nil, nil, err
916		}
917		if deviceID == "" {
918			return nil, nil, ErrInvalidDeviceID
919		}
920		i, ok := c.index[deviceID]
921		if !ok {
922			return nil, nil, fmt.Errorf("%w: %s", ErrDeviceNotInCampaign, deviceID)
923		}
924		return c, c.Devices[i], nil
925	}
