927	// DeviceStatusView 是一台设备在活动中的状态快照。
928	type DeviceStatusView struct {
929		DeviceID string
930		Batch    int
931		// Status 取 Device* 状态常量，含等待回滚、正在回滚、回滚成功、
932		// 回滚失败与回滚阶段超时。
933		Status string
934		// Phase 是设备当前停留或失败的阶段（download/install/rollback）。
935		Phase string
936		// Reason 是失败、超时或未执行（skipped）的原因；成功时为空。
937		Reason string
938		// At 是进入当前状态的时间。
939		At time.Time
940		// DownloadID/InstallID/RollbackID 是各阶段操作的稳定标识。
941		DownloadID string
942		InstallID  string
943		RollbackID string
944		// RollbackTarget 是开启回滚时首次领取下载锁定的回滚目标版本；未锁定为空。
945		RollbackTarget string
946		// InstallFailReason/InstallFailAt 是已接受的安装失败的原因与时间，
947		// 进入回滚后仍保留原值，便于与回滚结果分别查看。
948		InstallFailReason string
949		InstallFailAt     time.Time
950		// RollbackResult 表示是否已接受回滚结果。
951		RollbackResult bool
952		// RollbackSuccess 表示已接受的回滚结果是否成功。
953		RollbackSuccess bool
954		// RollbackReason/RollbackAt 是回滚结果（成功或失败）的原因与时间。
955		RollbackReason string
956		RollbackAt     time.Time
957	}
958	
959	// BatchView 是一个批次内所有设备的状态，按提交次序排列。
960	type BatchView struct {
961		Index   int
962		Devices []DeviceStatusView
963	}
964	
965	// CampaignView 是分批升级活动的只读快照。
966	type CampaignView struct {
967		ID            string
968		Operator      string
969		TargetVersion string
970		CreatedAt     time.Time
971		BatchSize     int
972		WindowStart   time.Time
973		WindowEnd     time.Time
974		Deadline      time.Time
975		// RollbackOnFailure 表示该活动是否开启安装失败回滚。
976		RollbackOnFailure bool
977		// Status 取 Campaign* 状态常量。
978		Status  string
979		Ended   bool
980		EndedAt time.Time
981		// Devices 按提交次序给出每台设备的状态。
982		Devices []DeviceStatusView
983		// Batches 按批次号分组，保留设备提交次序。
984		Batches []BatchView
985		// Results 是按接受顺序排列的结果历史（重复提交不产生新记录）。
986		Results []ResultRecord
987	}
988	
989	// GetCampaign 查询活动：创建者、目标版本、每批设备状态、
990	// 失败或超时原因及结果历史。返回数据为独立副本。
991	func (s *Store) GetCampaign(campaignID string) (CampaignView, error) {
992		s.mu.Lock()
993		defer s.mu.Unlock()
994		if err := s.checkOpen(); err != nil {
995			return CampaignView{}, err
996		}
997		c, err := s.lookupCampaign(campaignID)
998		if err != nil {
999			return CampaignView{}, err
1000		}
1001		v := CampaignView{
1002			ID:                c.ID,
1003			Operator:          c.Operator,
1004			TargetVersion:     c.Target,
1005			CreatedAt:         c.CreatedAt,
1006			BatchSize:         c.BatchSize,
1007			WindowStart:       c.WindowStart,
1008			WindowEnd:         c.WindowEnd,
1009			Deadline:          c.Deadline,
1010			RollbackOnFailure: c.RollbackOnFailure,
1011			Status:            c.Status,
1012			Ended:             c.Ended,
1013			EndedAt:           c.EndedAt,
1014			Results:           make([]ResultRecord, len(c.Results)),
1015		}
1016		copy(v.Results, c.Results)
1017		for _, cd := range c.Devices {
1018			dv := DeviceStatusView{
1019				DeviceID:       cd.DeviceID,
1020				Batch:          cd.Batch,
1021				Status:         cd.Status,
1022				Phase:          cd.Phase,
1023				Reason:         cd.Reason,
1024				At:             cd.At,
1025				DownloadID:     cd.Download.ID,
1026				InstallID:      cd.Install.ID,
1027				RollbackID:     cd.Rollback.ID,
1028				RollbackTarget: cd.RollbackTarget,
1029			}
1030			// 安装失败原因与时间独立保留，进入回滚后也不被回滚结果覆盖。
1031			if cd.Install.HasResult && !cd.Install.Success {
1032				dv.InstallFailReason = cd.Install.Reason
1033				dv.InstallFailAt = cd.Install.At
1034			}
1035			// 回滚结果的原因与时间单独呈现。
1036			if cd.Rollback.HasResult {
1037				dv.RollbackResult = true
1038				dv.RollbackSuccess = cd.Rollback.Success
1039				dv.RollbackReason = cd.Rollback.Reason
1040				dv.RollbackAt = cd.Rollback.At
1041			}
1042			v.Devices = append(v.Devices, dv)
1043			for len(v.Batches) <= cd.Batch {
1044				v.Batches = append(v.Batches, BatchView{Index: len(v.Batches)})
1045			}
1046			v.Batches[cd.Batch].Devices = append(v.Batches[cd.Batch].Devices, dv)
1047		}
1048		return v, nil
1049	}
1050	
1051	// DeviceWork 是设备当前版本与待执行操作的查询结果。
1052	type DeviceWork struct {
1053		DeviceID string
1054		Version  string
1055		Online   bool
1056		// CampaignID 是设备当前所在的未结束活动；没有时为空。
1057		CampaignID string
1058		// Pending 是设备仍待完成的操作（至多一个）：已领取未完成或下一阶段可领取。
1059		// 等待回滚时为尚未领取的回滚操作，其 TargetVersion 给出锁定的回滚目标。
1060		Pending *Operation
1061		// PendingClaimed 表示 Pending 是否已领取（未领取的安装或回滚仍须等维护窗口）。
1062		PendingClaimed bool
1063	}
1064	
1065	// GetDeviceWork 查询设备当前版本及其待执行操作。
1066	func (s *Store) GetDeviceWork(deviceID string) (DeviceWork, error) {
1067		s.mu.Lock()
1068		defer s.mu.Unlock()
1069		if err := s.checkOpen(); err != nil {
1070			return DeviceWork{}, err
1071		}
1072		d, err := s.lookup(deviceID)
1073		if err != nil {
1074			return DeviceWork{}, err
1075		}
1076		w := DeviceWork{DeviceID: deviceID, Version: d.Version, Online: d.Online}
1077		for id, c := range s.campaigns {
1078			if c.Ended {
1079				continue
1080			}
1081			i, ok := c.index[deviceID]
1082			if !ok {
1083				continue
1084			}
1085			cd := c.Devices[i]
1086			w.CampaignID = id
1087			if out := outstandingOp(c, cd); out != nil {
1088				w.Pending = out
1089				w.PendingClaimed = true
1090			} else if cd.Status == DeviceAwaitingRollback {
1091				// 回滚待领取：显示回滚目标，标记为尚未领取。
1092				w.Pending = &Operation{
1093					ID:            cd.Rollback.ID,
1094					CampaignID:    c.ID,
1095					DeviceID:      deviceID,
1096					Kind:          StageRollback,
1097					TargetVersion: cd.RollbackTarget,
1098				}
1099				w.PendingClaimed = false
1100			} else if !isTerminal(cd.Status) {
1101				kind := StageDownload
1102				id := cd.Download.ID
1103				if cd.Download.HasResult {
1104					kind, id = StageInstall, cd.Install.ID
1105				}
1106				w.Pending = &Operation{ID: id, CampaignID: c.ID, DeviceID: deviceID, Kind: kind}
1107				w.PendingClaimed = false
1108			}
1109			break
1110		}
1111		return w, nil
1112	}
1113	
1114	// ListUpgrades 返回已登记的全部升级目标版本，按目标版本字典序排列。
1115	func (s *Store) ListUpgrades() ([]VersionSpec, error) {
1116		s.mu.Lock()
1117		defer s.mu.Unlock()
1118		if err := s.checkOpen(); err != nil {
1119			return nil, err
1120		}
1121		out := make([]VersionSpec, 0, len(s.versions))
1122		for _, v := range s.versions {
1123			out = append(out, VersionSpec{Target: v.Target, AllowedFrom: append([]string(nil), v.AllowedFrom...)})
1124		}
1125		sort.Slice(out, func(i, j int) bool { return out[i].Target < out[j].Target })
1126		return out, nil
1127	}
